import java.util.*;class TaskBinding{static Object patient(long id,long card,String diagnosis){return new Patient(id,"L"+id,"F","M","Addr","0001",card,diagnosis);}static Object shortValue(){return new Patient(9,"Short");}static Object[]array(Object...a){return Arrays.copyOf(a,a.length,Patient[].class);}static Object[]diagnosis(Object[]a,String s){return Patient.diagnosis((Patient[])a,s);}static Object[]range(Object[]a,long lo,long hi){return Patient.range((Patient[])a,lo,hi);}static List<?>value(Object x){Patient p=(Patient)x;return List.of(p.id(),p.last(),p.first(),p.middle(),p.address(),p.phone(),p.card(),p.diagnosis());}static void edit(Object x){Patient p=(Patient)x;p.id(7);p.last("L");p.first("F");p.middle("M");p.address("A");p.phone("007");p.card(7);p.diagnosis("D");}static String text(Object x){return x.toString();}}
